package app.dawnbreaker.mobile;
import android.app.*;import android.content.*;import android.net.Uri;import android.webkit.CookieManager;import android.graphics.BitmapFactory;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;import java.util.zip.*;
class WallpaperProjects{
 final Context context;final String base;final File root,staging;static final int LIMIT=100*1024*1024;WallpaperProjects(Context c,String base){context=c;this.base=base;root=new File(c.getFilesDir(),"wallpapers");root.mkdirs();staging=new File(c.getCacheDir(),"wallpaper-pick");staging.mkdirs();}
 static boolean safe(String v){if(v==null||v.isEmpty()||v.length()>240||v.matches(".*[\\\\:\\x00-\\x1f].*")||v.startsWith("/"))return false;for(String s:v.split("/",-1))if(s.isEmpty()||s.equals(".")||s.equals("..")||s.endsWith(" ")||s.endsWith(".")||s.matches("(?i)(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(\\..*)?"))return false;return true;}
 File folder(String id)throws Exception{if(id==null||!id.matches("[a-f0-9]{32}"))throw new Exception("壁纸不存在");File f=new File(root,id);if(!f.isDirectory())throw new Exception("壁纸不存在");return f;}
 JSONObject manifest(File folder)throws Exception{try(InputStream in=new FileInputStream(new File(folder,"manifest.json"))){return new JSONObject(new String(DawnWarpService.read(in,65536),StandardCharsets.UTF_8));}}
 JSONObject pick(Uri uri)throws Exception{String name="resource";try(android.database.Cursor c=context.getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}if(!safe(name)||name.contains("/"))name="resource";String id=UUID.randomUUID().toString().replace("-","");File dir=new File(staging,id);dir.mkdirs();File file=new File(dir,name);try(InputStream in=context.getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(file)){copy(in,out,LIMIT);}return new JSONObject().put("handle",id).put("name",name).put("size",file.length());}
 File picked(String id)throws Exception{if(id==null||!id.matches("[a-f0-9]{32}"))throw new Exception("请重新选择资源");File[] files=new File(staging,id).listFiles();if(files==null||files.length!=1)throw new Exception("资源已失效，请重新选择");return files[0];}
 static void copy(InputStream in,OutputStream out,int limit)throws Exception{int total=0,n;byte[] b=new byte[32768];while((n=in.read(b))!=-1){if((total+=n)>limit)throw new Exception("文件超过大小限制");out.write(b,0,n);}}
 static void remove(File f){File[] files=f.listFiles();if(files!=null)for(File c:files)remove(c);f.delete();}
 void validate(JSONObject m,File folder)throws Exception{if(m.optInt("format")!=1||m.optString("title").trim().isEmpty()||m.optString("title").length()>80)throw new Exception("壁纸清单无效");JSONObject variants=m.getJSONObject("variants");if(variants.length()==0||variants.length()>2)throw new Exception("壁纸缺少端适配");for(Iterator<String> i=variants.keys();i.hasNext();){String key=i.next();JSONObject v=variants.getJSONObject(key);if(!Arrays.asList("desktop","mobile").contains(key)||!Arrays.asList("image","video","web").contains(v.optString("kind"))||!Arrays.asList("cover","contain").contains(v.optString("fit","cover")))throw new Exception("壁纸适配无效");String entry=v.optString("entry"),url=v.optString("url");if(entry.isEmpty()==url.isEmpty())throw new Exception("壁纸入口无效");if(!url.isEmpty()){URL u=new URL(url);if(!v.optString("kind").equals("web")||!u.getProtocol().equals("https")||u.getUserInfo()!=null)throw new Exception("网页壁纸需为 HTTPS 地址");}else{if(!safe(entry)||!new File(folder,entry).isFile())throw new Exception("壁纸入口不存在");String ext=v.getString("kind").equals("image")?"(?i).*\\.(png|jpe?g|webp|gif)":v.getString("kind").equals("video")?"(?i).*\\.(mp4|webm)":"(?i).*\\.html?";if(!entry.matches(ext))throw new Exception("入口格式与壁纸类型不符");}}}
 JSONObject installPicked(String id)throws Exception{File file=picked(id);if(file.length()>LIMIT)throw new Exception("壁纸包超过 100 MB");return install(file);}
 JSONObject install(File zip)throws Exception{String id=UUID.randomUUID().toString().replace("-","");File folder=new File(root,id);folder.mkdirs();try{Set<String> seen=new HashSet<>();int count=0,total=0;try(ZipInputStream in=new ZipInputStream(new FileInputStream(zip))){ZipEntry e;while((e=in.getNextEntry())!=null){if(e.isDirectory())continue;String name=e.getName();if(!safe(name)||!seen.add(name.toLowerCase(Locale.ROOT))||++count>512)throw new Exception("壁纸包路径或文件数无效");File dest=new File(folder,name);dest.getParentFile().mkdirs();try(OutputStream out=new FileOutputStream(dest)){int n;byte[] b=new byte[32768];while((n=in.read(b))!=-1){if((total+=n)>200*1024*1024)throw new Exception("壁纸解压后超过 200 MB");out.write(b,0,n);}}}}JSONObject m=manifest(folder);validate(m,folder);return new JSONObject().put("id",id).put("manifest",m);}catch(Exception e){remove(folder);throw e;}}
 String preview(File folder,JSONObject m){try{JSONObject variants=m.getJSONObject("variants");for(Iterator<String> keys=variants.keys();keys.hasNext();){JSONObject v=variants.getJSONObject(keys.next());if(v.optString("kind").equals("image")&&v.has("entry")){File file=new File(folder,v.getString("entry"));BitmapFactory.Options opts=new BitmapFactory.Options();opts.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getAbsolutePath(),opts);opts.inSampleSize=Math.max(1,Math.max(opts.outWidth,opts.outHeight)/480);opts.inJustDecodeBounds=false;android.graphics.Bitmap image=BitmapFactory.decodeFile(file.getAbsolutePath(),opts);if(image==null)return null;ByteArrayOutputStream bytes=new ByteArrayOutputStream();image.compress(android.graphics.Bitmap.CompressFormat.JPEG,75,bytes);image.recycle();return "data:image/jpeg;base64,"+android.util.Base64.encodeToString(bytes.toByteArray(),android.util.Base64.NO_WRAP);}}}catch(Exception ignored){}return null;}
 JSONObject list()throws Exception{JSONArray projects=new JSONArray();String active=context.getSharedPreferences("dawn-wallpaper",0).getString("active","");File[] folders=root.listFiles();if(folders!=null)for(File f:folders)try{if(f.getName().matches("[a-f0-9]{32}"))projects.put(new JSONObject().put("id",f.getName()).put("manifest",manifest(f)).put("preview",preview(f,manifest(f))).put("active",f.getName().equals(active)));}catch(Exception ignored){}return new JSONObject().put("projects",projects).put("active",active).put("platform","mobile");}
 File pack(String id)throws Exception{File folder=folder(id);File archive=new File(staging,"export-"+id+".dawnwallpaper");try(ZipOutputStream out=new ZipOutputStream(new FileOutputStream(archive))){packFolder(folder,folder,out);}if(archive.length()>LIMIT){archive.delete();throw new Exception("壁纸包超过 100 MB");}return archive;}
 void packFolder(File base,File folder,ZipOutputStream out)throws Exception{File[] children=folder.listFiles();if(children!=null)for(File f:children){if(f.isDirectory())packFolder(base,f,out);else{String key=base.toURI().relativize(f.toURI()).getPath();if(!safe(key)||key.startsWith(".dawn-"))continue;out.putNextEntry(new ZipEntry(key));try(InputStream in=new FileInputStream(f)){copy(in,out,200*1024*1024);}out.closeEntry();}}}
 void export(String id,Uri uri)throws Exception{File zip=pack(id);try(InputStream in=new FileInputStream(zip);OutputStream out=context.getContentResolver().openOutputStream(uri)){copy(in,out,LIMIT);}finally{zip.delete();}}
 JSONObject create(JSONObject o)throws Exception{String id=UUID.randomUUID().toString().replace("-","");File folder=new File(root,id);folder.mkdirs();try{JSONObject variants=new JSONObject(),input=o.getJSONObject("variants");for(Iterator<String> keys=input.keys();keys.hasNext();){String p=keys.next();if(!Arrays.asList("desktop","mobile").contains(p))throw new Exception("端适配无效");JSONObject v=input.getJSONObject(p),result=new JSONObject().put("kind",v.optString("kind")).put("fit",v.optString("fit","cover"));if(v.has("url"))result.put("url",v.getString("url"));else{File dest;if(v.has("markdown")){String entry=p+"/index.html";dest=new File(folder,entry);dest.getParentFile().mkdirs();try(OutputStream out=new FileOutputStream(dest)){out.write(v.getString("markdown").getBytes(StandardCharsets.UTF_8));}result.put("entry",entry);}else{File file=picked(v.optString("handle"));String ext=file.getName().contains(".")?file.getName().substring(file.getName().lastIndexOf('.')).toLowerCase(Locale.ROOT):"";String entry=p+"/asset"+ext;dest=new File(folder,entry);dest.getParentFile().mkdirs();try(InputStream in=new FileInputStream(file);OutputStream out=new FileOutputStream(dest)){copy(in,out,LIMIT);}result.put("entry",entry);}}variants.put(p,result);}JSONObject m=new JSONObject().put("format",1).put("title",o.optString("title").trim()).put("description",o.optString("description")).put("variants",variants);validate(m,folder);try(OutputStream out=new FileOutputStream(new File(folder,"manifest.json"))){out.write(m.toString().getBytes(StandardCharsets.UTF_8));}return new JSONObject().put("id",id).put("manifest",m);}catch(Exception e){remove(folder);throw e;}}
 HttpURLConnection server(String path,String method)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(base+"/api/plugins/wallpaper"+path).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(180000);c.setInstanceFollowRedirects(false);c.setRequestMethod(method);String cookies=CookieManager.getInstance().getCookie(base);if(cookies!=null)c.setRequestProperty("Cookie",cookies);return c;}
 JSONObject cloud(String command,JSONObject o)throws Exception{if(command.equals("wallpaper.publish")){File zip=pack(o.getString("id"));String boundary="Dawn"+UUID.randomUUID().toString().replace("-","");HttpURLConnection c=server("","POST");try{c.setDoOutput(true);c.setChunkedStreamingMode(32768);c.setRequestProperty("Content-Type","multipart/form-data; boundary="+boundary);try(OutputStream out=c.getOutputStream();InputStream in=new FileInputStream(zip)){out.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"file\"; filename=\"wallpaper.dawnwallpaper\"\r\nContent-Type: application/zip\r\n\r\n").getBytes(StandardCharsets.UTF_8));copy(in,out,LIMIT);out.write(("\r\n--"+boundary+"--\r\n").getBytes(StandardCharsets.UTF_8));}if(c.getResponseCode()==403)throw new Exception("仅管理员可以上传云端壁纸");if(c.getResponseCode()>=300)throw new Exception("云端发布失败");try(InputStream in=c.getInputStream()){return new JSONObject(new String(DawnWarpService.read(in,65536),StandardCharsets.UTF_8));}}finally{c.disconnect();zip.delete();}}
 String id=o.optString("id");if(!id.matches("[a-f0-9]{32}"))throw new Exception("壁纸不存在");HttpURLConnection c=server("/"+id+"/file","GET");File zip=new File(staging,"download-"+id+".zip");try{if(c.getResponseCode()!=200)throw new Exception("壁纸下载失败");try(InputStream in=c.getInputStream();OutputStream out=new FileOutputStream(zip)){copy(in,out,LIMIT);}MessageDigest hash=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(zip)){byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1)hash.update(b,0,n);}StringBuilder digest=new StringBuilder();for(byte b:hash.digest())digest.append(String.format("%02x",b));if(!digest.toString().equals(o.optString("sha256")))throw new Exception("壁纸校验失败");return install(zip);}finally{c.disconnect();zip.delete();}}
 JSONObject action(String command,JSONObject o,Activity activity)throws Exception{switch(command){case"wallpaper.list":return list();case"wallpaper.create":return create(o);case"wallpaper.publish":case"wallpaper.download":return cloud(command,o);case"wallpaper.delete":String id=o.getString("id");if(id.equals(context.getSharedPreferences("dawn-wallpaper",0).getString("active","")))throw new Exception("请先在系统壁纸设置中更换当前壁纸");remove(folder(id));return list();case"wallpaper.stop":context.getSharedPreferences("dawn-wallpaper",0).edit().putBoolean("paused",true).apply();return new JSONObject();case"wallpaper.apply":File folder=folder(o.getString("id"));JSONObject variant=manifest(folder).getJSONObject("variants").optJSONObject("mobile");if(variant==null)throw new Exception("此壁纸没有手机端适配");if(variant.getString("kind").equals("image")){try(InputStream in=new FileInputStream(new File(folder,variant.getString("entry")))){android.app.WallpaperManager.getInstance(context).setStream(in);}context.getSharedPreferences("dawn-wallpaper",0).edit().putString("active",o.getString("id")).putBoolean("paused",false).commit();}else{if(variant.getString("kind").equals("web")&&android.os.Build.VERSION.SDK_INT<28)throw new Exception("隔离网页壁纸需要 Android 9 或更新版本");context.getSharedPreferences("dawn-wallpaper",0).edit().putString("candidate",o.getString("id")).putBoolean("paused",false).commit();activity.runOnUiThread(()->activity.startActivity(new Intent(android.app.WallpaperManager.ACTION_CHANGE_LIVE_WALLPAPER).putExtra(android.app.WallpaperManager.EXTRA_LIVE_WALLPAPER_COMPONENT,new ComponentName(context,DawnWallpaperService.class))));}return list();default:throw new Exception("未知壁纸操作");}}
}
